// JS -> WASM control surface (exported); see www/index.html for the caller side
// ---------------------------------------------------------------------------

/// Start the Bevy app on the given canvas (CSS selector). Returns immediately;
/// all further control goes through the queued messages below. `asset_root` is
/// the base every asset path (radar PNG, map glTF + its textures) resolves
/// against — on wasm it becomes the fetch() URL prefix. `None` keeps Bevy's
/// page-relative "assets" default (the standalone www/ dev page). `cs2_models` picks
/// the real CS2 characters over the fallback soldier; the page only passes true when
/// those (never committed) files exist, because a missing model means no players at all.
/// `cs2_weapons` does the same for the guns, where a missing file only means a simple
/// box in its place, and a 404 in the console that the page would rather not cause.
#[wasm_bindgen]
pub fn run(canvas_selector: String, asset_root: Option<String>, cs2_models: Option<bool>, cs2_weapons: Option<bool>) {
    console_error_panic_hook::set_once();
    App::new()
        .insert_resource(ClearColor(util::hex_color("#0b0e14")))
        .insert_resource(Viewer::default())
        .insert_resource(scene::UseCs2Models(cs2_models.unwrap_or(false)))
        .insert_resource(weapons_viz::RealWeapons::new(cs2_weapons.unwrap_or(false)))
        .insert_resource(orbit::OrbitCam::default())
        .insert_resource(LabelsOut::default())
        .insert_resource(PlayerPoses::default())
        .insert_resource(TracersOut::default())
        .add_plugins(
            DefaultPlugins
                .set(WindowPlugin {
                    primary_window: Some(Window {
                        canvas: Some(canvas_selector),
                        fit_canvas_to_parent: true,
                        prevent_default_event_handling: false,
                        ..default()
                    }),
                    ..default()
                })
                .set(AssetPlugin {
                    file_path: asset_root.unwrap_or_else(|| "assets".into()),
                    // no .meta files exist; skip a 404 fetch per asset on wasm
                    meta_check: AssetMetaCheck::Never,
                    ..default()
                }),
        )
        .add_plugins(map_material::MapMaterialPlugin)
        .init_asset::<textured_map::MapGeo>()
        .init_asset_loader::<textured_map::MapGeoLoader>()
        .init_gizmo_group::<TracerGizmos>()
        .add_systems(
            Startup,
            (setup, scene::setup_player_model, setup_tracer_gizmos, weapons_viz::setup_weapon_assets),
        )
        .add_systems(
            Update,
            (
                drain_controls,
                scene::finish_player_model,
                scene::finish_action_clips,
                player_rig::prepare_round_anim,
                spawn_round_players,
                advance_clock,
                update_players,
                update_utility,
                draw_tracers,
                draw_grid,
                orbit::orbit_camera,
                spectator_camera,
                sync_xray_camera,
                report_frame,
            )
                .chain(),
        )
        .add_systems(
            Update,
            (
                hide_tool_brushes,
                player_rig::setup_player_anim,
                player_rig::drive_player_anim,
                tint_players,
                player_rig::update_corpse_layers,
                fade_team_colour,
                weapons_viz::finish_real_weapons,
                weapons_viz::update_weapon_mounts,
                weapons_viz::update_viewmodel,
                textured_map::finish_map_load,
                textured_map::apply_map_textures,
                textured_map::sky_follow_camera.after(spectator_camera),
                textured_map::light_players_like_the_map,
            ),
        )
        // on top of the clips' pose and before it reaches the skinned mesh
        .add_systems(
            PostUpdate,
            player_rig::apply_player_aim
                .after(AnimationSystems)
                .before(bevy::transform::TransformSystems::Propagate),
        )
        .run();
}

/// Feed manifest.json's text (greybox + team colors + camera framing).
#[wasm_bindgen]
pub fn load_manifest(json: String) {
    push_control(ControlMsg::LoadManifest(json));
}

/// Feed one round's raw .3dr bytes. Decodes synchronously and returns the round's
/// header JSON (players, weaponTable, utility, nSamples, ...) for the page UI.
#[wasm_bindgen]
pub fn load_round(bytes: &[u8]) -> Result<String, JsValue> {
    let dec = c2r3::decode_round(bytes).map_err(|e| JsValue::from_str(&e.to_string()))?;
    let header = serde_json::to_string(&dec.header).map_err(|e| JsValue::from_str(&e.to_string()))?;
    push_control(ControlMsg::LoadRound(Box::new(dec)));
    Ok(header)
}

#[wasm_bindgen]
pub fn seek(t: f64) {
    push_control(ControlMsg::Seek(t));
}

#[wasm_bindgen]
pub fn set_playing(playing: bool) {
    push_control(ControlMsg::SetPlaying(playing));
}

#[wasm_bindgen]
pub fn set_speed(speed: f64) {
    push_control(ControlMsg::SetSpeed(speed));
}

/// `?flash=<playerName>` deep-link: whose flash channel drives the page overlay.
#[wasm_bindgen]
pub fn set_flash_focus(name: Option<String>) {
    push_control(ControlMsg::SetFlashFocus(name));
}

/// Map/Radar toggle: show the real map geometry (true) or the radar greybox (false).
#[wasm_bindgen]
pub fn set_map_visible(on: bool) {
    push_control(ControlMsg::SetShowMap(on));
}

/// Spectate a player: lock the camera to `slot`'s POV, first-person (through their
/// eyes) when `first_person`, otherwise a third-person chase cam behind them.
#[wasm_bindgen]
pub fn set_camera_follow(slot: u32, first_person: bool) {
    push_control(ControlMsg::SetCamFollow { slot: slot as usize, first_person });
}

/// Release the spectator camera back to free orbit.
#[wasm_bindgen]
pub fn set_camera_free() {
    push_control(ControlMsg::SetCamFree);
}

/// Toggle the x-ray overlay: when on (default), players are drawn on top of walls
/// and smoke so you can always see them, like a demo watched with wallhack.
#[wasm_bindgen]
pub fn set_xray(on: bool) {
    push_control(ControlMsg::SetXray(on));
}

// ---------------------------------------------------------------------------
// WASM -> JS per-frame report. Flat f32 payload (see index.html for the layout):
// [clock, duration, playing, flashOpacity, nPlayers, nTracers,
//  {x, y, onScreen, alive, health, weapon, worldX, worldY, yawDeg, present} * nPlayers,
//        (x,y normalized viewport coords, valid when onScreen; alive/health are
//         real per-frame state independent of projection — drives the spec panel;
//         weapon table idx; worldX/worldY/yawDeg are RAW demo coords for the
//         page radar — dead players hold their death spot; present=0 -> no
//         radar marker at all)
//  {utilIdx, x, y, opacity} * nTracers]
// KEEP THE PER-PLAYER STRIDE (10) IN LOCKSTEP with both HTML readers
// (rust/viewer/www/index.html + web/templates/replay3d.html, PSTRIDE const).
// ---------------------------------------------------------------------------

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen]
extern "C" {
    #[wasm_bindgen(js_namespace = window, js_name = __replayFrame)]
    fn replay_frame(data: &[f32]);
}

#[cfg(not(target_arch = "wasm32"))]
fn replay_frame(_data: &[f32]) {}

/// Per-player render/report state from update_players, consumed by report_frame.
/// `draw_nametag` is false for a first-person self (own name hidden); `alive`/`health`
/// stay real regardless, so the spectator panel shows every player's true state.
/// `wx`/`wy`/`yaw_deg` are RAW demo-world values (pre scene-scale/axis-swap) — the
/// page radar projects them with the manifest's calibration (mapscal formula).
/// Dead players keep their frozen death position so the radar can draw an ✕ there.
struct LabelInfo {
    anchor: Vec3,
    draw_nametag: bool,
    alive: bool,
    hp: u8,
    wpn: u8,
    wx: f32,
    wy: f32,
    yaw_deg: f32,
    present: bool,
}

#[derive(Resource, Default)]
struct LabelsOut(Vec<LabelInfo>);

/// One player's interpolated eye pose for the spectator camera (scene space).
#[derive(Clone, Copy)]
struct PlayerPose {
    /// feet position (the player origin, matching the model anchor)
    feet: Vec3,
    /// world yaw as a scene +Y rotation, radians
    yaw: f32,
    /// Source eye pitch, radians (+ = looking down)
    pitch: f32,
    crouch: bool,
}

/// Per-slot eye pose for `spectator_camera` (populated by update_players).
/// `None` = dead / absent / no round this frame.
#[derive(Resource, Default)]
struct PlayerPoses(Vec<Option<PlayerPose>>);

/// Tracer label anchors from update_utility: (utility index, tip, opacity).
#[derive(Resource, Default)]
struct TracersOut(Vec<(usize, Vec3, f32)>);

